def ts(c):
    return '0x' + format(c, '06x')


def main():
    ids = [f[0] for f in F]
    assert len(ids) == len(set(ids))
    # fighters.json
    fj = ROOT / 'public' / 'fighters.json'
    roster = [f for f in json.loads(fj.read_text()) if f['id'] not in ids]
    for i, f in enumerate(F):
        fid, name, handle, *_ = f
        archetype, playstyle = f[8], f[9]
        specials, (fname, fdesc, _) = f[11], f[12]
        roster.append({
            'id': fid, 'order': 7 + i, 'name': name, 'handle': handle, 'cardNameplate': name.upper(),
            'archetype': archetype, 'playstyle': playstyle,
            'specials': [{'name': n, 'description': d} for n, d, _ in specials],
            'fatality': f'{fname}: {fdesc}', 'card': f'assets/cards/{fid}.webp',
        })
    roster.sort(key=lambda f: f['order'])
    fj.write_text(json.dumps(roster, indent=2, ensure_ascii=False) + '\n')

    def block(path, open_marker, entries):
        p = ROOT / path
        s = p.read_text()
        start = s.index(open_marker)
        end = s.index('\n};', start)
        body = s[start:end]
        body = re.sub(r'\n  // batch 5 \(generated by scripts/batch5_fighters\.py\)[\s\S]*$', '', body)
        p.write_text(s[:start] + body + '\n  // batch 5 (generated by scripts/batch5_fighters.py)\n' + entries + s[end:])

    q = lambda x: f"'{x}'" if '-' in x or x[0].isdigit() else x
    block('src/data/tuning.ts', 'const T: Record<string, Row> = {',
          '\n'.join(f"  {q(f[0])}: ['{f[3]}', {f[4]}, {f[5]}, {f[6]}, false, {ts(f[7])}, {json.dumps(f[10], ensure_ascii=False)}]," for f in F))
    block('src/data/moves.ts', 'export const MOVES: Record<string, FighterMoves> = {',
          '\n'.join(f"  {q(f[0])}: [\n" + ''.join(f'    {spec},\n' for _, _, spec in f[11]) + '  ],' for f in F))
    block('src/fight/fatalities.ts', 'const SCRIPTS: Record<string, Script> = {',
          '\n'.join(f"  {q(f[0])}: (k) => {{\n" + ''.join(f'    {line}\n' for line in f[12][2]) + '  },' for f in F))
    # announcer name calls
    vp = ROOT / 'scripts' / 'make_voices.py'
    v = vp.read_text()
    v = re.sub(r'\n    # batch 5[\s\S]*?# end batch 5', '', v)
    anchor = '    "mystayor":'
    i = v.index(anchor)
    i = v.index('\n', i) + 1
    v = v[:i] + '    # batch 5\n' + ''.join(f'    "{f[0]}": {json.dumps(f[13])},\n' for f in F) + '    # end batch 5\n' + v[i:]
    vp.write_text(v)
    print('wrote', len(F), 'fighters')


if __name__ == '__main__':
    main()
